                        new
                        {
                            Id = 20,
                            Author = "أحمد عصام الدين",
                            CategoryId = 6,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "أجلسُ بصحبةِ قلمٍ فضيٍّ شُجَّ رأسُه، وجفَّ الجرحُ.\nأريدُ أن أحكي قبل أن يفرغ حبرُه.\nأجدُ نفسي أرسمُ مجددًا.\n\nأرسمُ أعينًا، وأبوابًا، وأمواجًا.\nأرسمُ شيخًا يحمل طفلًا لم يتقبّل فكرة انتهاء مدة اللعب.\nأرسمُ شابًا تائهًا، غارقًا في ملابس البالغين الفضفاضة.\nأرسمُ فندقًا يُعجب صاحبُه بازدحامه، ولا يفهم أن الزائر يبيت بضع ليالٍ ثم يرحل بلا عودة.\nأرسمُ صاحبَ سيركٍ يُلاعب قردًا.\nأرسمُ سريرًا، تحته مقبرةٌ تُدفن فيها الأحلام الضائعة.\n\nأتأملُ ما رسمتُه، فأجدني موجودًا في كل شيء.\nأنا الطفلُ، والشابُ، والشيخ.\nأنا صاحبُ الفندق وزبونُه.\nأنا الزائرُ والمقيم.\nأنا صاحبُ السيرك والمشاهد.\nأنا القردُ والطبلة.\nأنا الذي حفرتُ المقبرة، وأنا من بكيت.\nأنا من دفنتُ الأحلام بيدي.\n\nيئستُ من تحقيقها.\nتخلّيتُ بعدما تمسّكت.\nأطفأتُ المصباح، فاستحالت الألوانُ إلى أسودَ قاتم.\nحاولتُ أن أمحو آثارَ الأحلام، لكنها كانت تعود بعد النوم.\nتدبّ فيها الحياةُ لدقائق، لتذكّرني بأيامٍ ولّت،\nوتتساءل في أسف:\nبأيِّ ذنبٍ دُفِنتُ؟",
                            ImageUrl = "/images/products/9789778203264.webp",
                            Isbn = "9789778203264",
                            Name = "إنطفاء مصباح",
                            Pages = 172,
                            Price = 180m,
                            PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Size = "14×20",
                            Stock = 10,
                            TopRated = false
                        },
                        new
                        {
                            Id = 21,
                            Author = "سيسيليا اهيرن",
                            CategoryId = 6,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "تخيّل عالمًا ترى فيه الحقيقة بلا أقنعة.\nترى الناس كما هم فعلًا.\nمشاعرهم، نواياهم، أسرارهم، وحتى أكاذيبهم.\n\nمن العيش في عزلة خلف نظارات شمسية وقفازات، إلى حياة تفيض فيها الألوان بكل درجاتها، تبدأ أليس رحلة البحث عن ذات لا تذوب في الآخرين.\nرحلة شاقة نحو الفهم.\nنحو القبول.\nونحو النجاة.\n\nهذه ليست رحلة إلى الخارج، بل إلى الداخل.\nحيث المواجهة الأصعب.\n\nرواية عن رؤية ما لا يراه الآخرون.\nوعن عالم واحد… يمكن أن يُرى بألف طريقة مختلفة.",
                            ImageUrl = "/images/products/9789778203103.webp",
                            Isbn = "9789778203103",
                            Name = "بألف طريقة مختلفة",
                            Pages = 360,
                            Price = 400m,
                            PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Size = "14×20",
                            Stock = 10,
                            TopRated = false
                        },
                        new
                        {
                            Id = 22,
                            Author = "رامي احمد مصطفى",
                            CategoryId = 6,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "زائرة مجهولة بفستان زفاف.\nبلاغ مرتبك عن جريمة قتل.\nواختفاء يربك كل ما يبدو واضحًا.\n\nمن شذرات متفرقة ومعطيات ناقصة، أجد نفسي مدفوعةً إلى خوض تجربتي الأولى في الكتابة.\nلا بوصفها بحثًا عن حل.\nبل كتجربة يحركها الفضول والشك.\n\nالنص لا يعد بإجابات.\nولا يمنح يقينًا.\nإنه اقتراب بطيء من لغز.\nواعتراف بأن بعض القصص لا تُحكى… بل تُعاش.\n“و.م”",
                            ImageUrl = "/images/products/9789778203356.webp",
                            Isbn = "9789778203356",
                            Name = "بعض ما ورد بشأنها",
                            Pages = 248,
                            Price = 230m,
                            PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Size = "14×20",
                            Stock = 10,
                            TopRated = false
                        },
                        new
                        {
                            Id = 23,
                            Author = "كيتلين شنايدرهان",
                            CategoryId = 3,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "لا تؤدّي كلُّ الطرق إلى النجاة، فأحيانًا ما تكون مجرّد بداية، كأغنيةٍ بعيدة تأتي من مكانٍ مجهول، ثم تعلو.. حتى تصير صراخًا يسكن الرأس.\nفي «تحليق إيكاروس» لا تقف الكارثة عند حدود بلدة صغيرة، بل تبدأ من داخلها؛ من رغبةٍ جارفةٍ في الخلاص، من حلمٍ بأن يصبح المرء ذو قيمة، ومن خطوةٍ واحدة نحو ضوء يبدو جميلًا، يعد بالأمل.. ويُخفي الاحتراق.\nولا تبدأ الحكاية بطفلٍ صغير يختفي دون أثر، أو بوحشٍ يخرج من الظلام، بل بشابٍّ.. يظن أن الخروج من البلدة هو النجاة، وأن الموسيقى هي الوسيلة المثلى لتحقيق هدفه.\nلكن بعض الأبواب لا تُفتح إلا لتريك ما لا ينبغي أن يُرى، وبعض الفرص تعدنا بالأمل.. وتُخفي في باطنها العذاب.\n«تحليق إيكاروس» ليست مجرّد رواية عادية، بل عمل سيترك في قلبك ندبةً لا تُرى.",
                            ImageUrl = "/images/products/9789778203257.webp",
                            Isbn = "9789778203257",
                            Name = "تحليق إيكاروس",
                            Pages = 364,
                            Price = 400m,
                            PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Size = "14×20",
                            Stock = 10,
                            TopRated = false
                        },
                        new
                        {
                            Id = 24,
                            Author = "طاهرة ماڤي",
                            CategoryId = 4,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "نغوص مع وارنر وكينجي في بحر من المشاعر الجياشة والتفاني المطلق، بينما يواجهان سباقًا مع الزمن لإنقاذ جولييت والحفاظ على حياتها. تدخل جولييت في غيبوبة غامضة، تاركة خلفها فراغًا ثقيلًا يدفع وارنر وكينجي إلى مواجهة قرارات مصيرية.\n\nفي الوقت نفسه، يتصاعد التوتر مع احتجاز أندرسون لجيمس وآدم وبقية أطفال القادة العُليا كرهائن، ما يجعل التحديات أكثر تعقيدًا وخطورة. يزخر هذا الجزء بالمنعطفات المدهشة والأحداث غير المتوقعة التي تطرح أسئلة ملحّة: هل ستنجو جولييت؟ وكيف سيتمكن أصدقاؤها من تحرير الرهائن ومواجهة أندرسون؟ والأهم… هل سينجحون في الإطاحة بنظام «إعادة التأسيس» إلى الأبد؟",
                            ImageUrl = "/images/products/9789778202571.webp",
                            Isbn = "9789778202571",
                            Name = "تخيلني",
                            Pages = 430,
                            Price = 455m,
                            PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Size = "14×20",
                            Stock = 10,
                            TopRated = false
                        },
                        new
                        {
                            Id = 25,
                            Author = "محمد عصمت",
                            CategoryId = 9,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "ما خُتِمَ بالملح… لا يذوب\nفي بلدةٍ ساحليةٍ يبدو كلُّ شيءٍ مألوفًا، حتى تبدأ الأمور بالتغيّر.\nتظهر تماثيل ملح في كل مكان، على الشواطئ وفي الزوايا، بلا صانعٍ معروف، ولا سببٍ مقنع.\nيحاول الجميع التعامل معها كأسطورةٍ قديمة، أو كوسيلة دعاية جديدة، قبل أن تتطوّر الأمور، وينتشر الملح ليفرض سطوته على كل شيء، كلما ظنّ الجميع أن الأمر قد انتهى.\n\nسرعان ما يجد سليم خطّاب، كاتب الرعب الشهير، الذي يعاني من مشكلات لا يمكن لأحد تصوّرها، نفسه متورّطًا في قلب الرعب؛ ويجد نفسه محاصرًا بأسئلةٍ عليه العثور على إجابتها.\nما علاقة هذه التماثيل برواياته؟ ولماذا يبدو أن البلدة تتصرّف كمن يُخفي لعنةً قديمة؟ وهل سيحتاج للبحث عن الناجين من الأساطير المرعبة ليجد ضالته بينهم؟\n\nقبل أن يدرك أن كل إجابة تقوده إلى سؤالٍ أشدّ ظلمة، وكل خطوة تقوده نحو حقيقةٍ لا يرغب في معرفتها… حيث لا يكون الماء ماءً فقط، ولا الملح ملحًا فحسب.\n\nفي «تماثيل الملح»، تذوب الرواية بين الأسطورة القديمة، وتتداخل مع الواقع، حتى لا تعود قادرًا على الفصل بين ما تراه… وما يريدك الملح أن تراه.",
                            ImageUrl = "/images/products/9789778203240.webp",
                            Isbn = "9789778203240",
                            Name = "تماثيل الملح",
                            Pages = 198,
