                        new
                        {
                            Id = 30,
                            Author = "إبراهيم عبدالعزيز",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "كتاب طه حسين: الأيام المنسية، يعيد فتح الصفحات التي لم تُكتب..\nويكمل ما توقف عنده عميد الأدب العربي طه حسين في سيرته الأشهر.\nليست سيرة تقليدية، بل كشف مباشر عبر رسائل خاصة وأوراق شخصية ونصوص لم تُنشر من قبل.\nكتاب يضعك أمام طه حسين الحقيقي\nبعقله وشكّه وإرادته التي صنعت نورًا من العتمة.",
                            ImageUrl = "/images/products/9789778203332.webp",
                            Isbn = "9789778203332",
                            Name = "طه حسين الأيام المنسية",
