                        new
                        {
                            Id = 32,
                            Author = "طاهر المعتز بالله",
                            CategoryId = 8,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "الحكي أقدم وسيلة ترفيه وتعلّم في التاريخ، قبل المسرح، وقبل الكتابة، وقبل كل شيء. القصص ملأت الأديان، وشكّلت وعي البشر.\nلكن لماذا تنجح بعض القصص وتفشل أخرى؟ وما الذي يصنع الكاتب العظيم؟ الشغف، الالتزام، وحب المعرفة.\nصفات جمعت بين كتّاب وصلوا إلى قمة الإبداع، وأثبتوا أن اسم الكاتب يمكن أن يكون عنصر جذب لا يقل عن النجوم.\nنجيب محفوظ، كريستوفر نولان، وجي كي رولينج. عباقرة جمعوا بين الفن والنجاح الجماهيري، خاطبوا القلوب والعقول، وأتقنوا هندسة المشاعر.\nدروس يمكن تعلّمها، لكن يبقى السؤال: ما ثمن العبقرية، وكيف نصل إليها؟",
                            ImageUrl = "/images/products/9789778203202.webp",
                            Isbn = "9789778203202",
                            Name = "عباقرة الكتابة",
                            Pages = 312,
                            Price = 250m,
                            PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
