                        new
                        {
                            Id = 34,
                            Author = "محمد كامل",
                            CategoryId = 3,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "بلاغ عن حريق لا يترك أثرًا.\nوقصر يخفي أكثر مما يُظهر.\nتحقيق في واقعة غامضة يقود إلى لغز يتجاوز المنطق والزمن.\n\nغرفة مرايا تفتح أبوابًا غير متوقعة.\nأزمنة تتقاطع على نحو غير متوقع.\nوتاريخ يسير في مسارات لم تحدث يومًا.\nكل انتقال يكشف سرًا جديدًا.\nوكل محاولة للعودة تقود إلى زمن أكثر خطورة.\n\nرواية تمزج التحقيق بالغموض.\nوتطرح سؤالًا واحدًا يلاحق القارئ حتى النهاية.\nهل القصر شاهد على ما حدث… أم صانع له؟",
                            ImageUrl = "/images/products/9789778203233.webp",
                            Isbn = "9789778203233",
                            Name = "قصر البارون",
                            Pages = 216,
                            Price = 200m,
