                        new
                        {
                            Id = 36,
                            Author = "كنزي مدبولي",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "ليست كل الحكايات تُروى بصوت واحد.\nوليست كل النساء ينجون…\nفي لستُ الأخيرة\nتتقاطع حيوات نساء من أزمنة وأماكن مختلفة..\nروما في القرن السابع عشر والإسكندرية في الحاضر.\nامرأة تصنع خلاصها بيديها.\nوأخرى تحاول إنقاذ غيرها قبل أن يفوت الأوان.\nقصص عن العنف، عن النجاة، وعن الثمن الذي تدفعه النساء حين يقررن ألا يكنّ الضحية التالية..\nرواية عن قوة تُولد من العجز،وعن رحمة قد تتحول إلى حمل ثقيل، وعن سؤال يرفض أن يختفي!!\nهل تنتهي الدائرة،أم أن هناك دائمًا ضحية جديدة؟",
                            ImageUrl = "/images/products/9786339957536.webp",
                            Isbn = "9786339957536",
                            Name = "لستُ الأخيرة",
                            Pages = 272,
                            Price = 260m,
                            PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
