                        new
                        {
                            Id = 39,
                            Author = "د. خولة حمدي",
                            CategoryId = 2,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "سفينة غارقة، وأسرار لم يعد ممكنًا إخفاؤها.\nبين سكان خائفين، ومرتزقة يبحثون عن النجاة…\nمادرا تتناقص، وأنفاق غامضة…\nقرار قد ينقذ الجميع، أو يحرق كل شيء…\nهذه ليست نهاية الرحلة… هذه لحظة الاختبار الحقيقي.\nهل يواجه آدم ثمن اختياره؟\nماذا حلّ بروان؟\nوهل يعود مايك…؟\nمن سينجو؟\nومن ستبتلعه النار؟",
                            ImageUrl = "/images/products/9789778203288.webp",
