                        new
                        {
                            Id = 51,
                            Author = "نهي داود",
                            CategoryId = 3,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "\"جثا المحقق على ركبتيه بجوار الجثة المنكفئة على أرض المكتب يتأمّل الجرح النافذ على الجبهة والثقب الذي توسّط الصدغ والدماء المتخثرة من حولها وتساءل: \"معقولة تكون انتحار؟\".\n***\nتبدأ الرواية بجثة منكفئة وتساؤل حائر وعيون محدّقة، وتنتهي بالحقيقة.. وبين البداية والنهاية تتشابك الأحداث، ما بين  حب مستحيل، ومعاملات مالية مشبوهة، ودوافع غير أخلاقية، وقلوب معلقة بالأمل، وقاتل مجهول، ومطر كاشف!\nنهى داود كاتبة مصرية ولدت في إنجلترا عام 1975، تخرجت في قسم الاتصالات بكلية الهندسة جامعة القاهرة. وبعد أن عملت بمجال تخصصها لسنوات غمرها تيار الشغف، لتعكف على كتابة أولى رواياتها البوليسية بعد أن حصلت على دبلومة الكتابة الإبداعية من جامعة ويزليان الأمريكية، ثم تخصصت الكاتبة في أدب الجريمة. صدر لها 9 روايات منها: \"رضا\"،  و\"جثتان والثالثة عند قدمي\"، و\"دماء على السجادة الحمراء\"، و\"ذبابة زرقاء\".",
                            ImageUrl = "/images/products/9789777955478.webp",
                            Isbn = "9789777955478",
                            Name = "جريمة في ليلة ممطرة",
                            Price = 235m,
                            PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Stock = 10,
