                        new
                        {
                            Id = 76,
                            Author = "نهى داود",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "ماذا تعرفون عن الحب؟\nهو قرص من عسل أو ورد على سياج بعيد؟\nوماذا إذا التقى الحبيبان بعد فراق طويل؟ فراق لم يقضِ على حبهما بل أججه في قلبيهما كجمرة مشتعلة تحت الرماد.\nيا لروعة اللقاء الثاني.. وأحلامه.. ووعوده.. ووروده.\nولكن هذه رواية جريمة!\nفهل سيكون اللقاء الثاني نورًا وقُبلة حياة لفدوى ووليد؟ أم سينقلب إلى نار تحرق الجميع؟\nرواية تبدأ بقتل وقصة حب.. فأين ستنتهي؟ وكيف يمكن للعدالة العمياء أن تتحقق بين أتون المشاعر المتشابكة وأسرار الماضي القاتمة؟\nنهى داود، كاتبة مصرية ولدت في إنجلترا عام 1975م، تخرجت في قسم الاتصالات بكلية الهندسة جامعة القاهرة. وبعد أن عملت بمجال تخصصها لسنوات غمرها تيار الشغف، لتعكف على كتابة أولى رواياتها البوليسية بعد أن حصلت على دبلومة الكتابة الإبداعية من جامعة ويزليان الأمريكية، ثم تخصصت الكاتبة في أدب الجريمة. صدر لها 9 روايات منها: \"رضا\"،  و\"جثتان والثالثة عند قدمي\"، و\"دماء على السجادة الحمراء\"، و\"ذبابة زرقاء\".",
                            ImageUrl = "/images/products/9789777955652.webp",
                            Isbn = "9789777955652",
