                        new
                        {
                            Id = 131,
                            Author = "ليندزي س. جيبسون",
                            CategoryId = 6,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "من أكثر الكتب مبيعًا في مجال علم النفس\nإذا نشأت مع والد غير ناضج عاطفيًّا أو غير متاح أو أناني، فقد تكون لديك مشاعر دائمة من الغضب أو الوحدة أو الخيانة أو الهجر، قد تتذكر طفولتك على أنها الوقت الذي لم تتم فيه تلبية احتياجاتك العاطفية، أو تم فيه تجاهل مشاعرك، أو توليت فيه مسؤولية أكبر من سنك في محاولة للتعويض عن سلوك والديك. يمكن أن تلتئم هذه الجروح، ويمكنك المُضي قُدمًا في حياتك.\nفي هذا الكتاب الرائع، تكشف عالمة النفس السريري ليندزي س. جيبسون الطبيعة المدمرة للآباء غير الناضجين عاطفيًّا أو الآباء غير المتاحين. سترى كيف يخلق هؤلاء الآباء شعورًا بالإهمال، وتكتشف طرقًا للشفاء من الألم والارتباك اللذين سبَّبتهما طفولتك. من خلال تحرير نفسك من عدم النضج العاطفي لوالديك، يمكنك استعادة طبيعتك الأصلية، والتحكم في طريقة تفاعلك معهما، وتجنب خيبة الأمل. وأخيرًا، ستتعلم كيفية إنشاء علاقات إيجابية وجديدة حتى تتمكن من بناء حياة أفضل.",
                            ImageUrl = "/images/products/9789778721980.webp",
                            Isbn = "9789778721980",
                            Name = "أبناء بالغون لوالدين غير ناضجين عاطفيا",
                            Pages = 272,
                            Price = 175m,
                            PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
