                        },
                        new
                        {
                            Id = 140,
                            Author = "نيقولا ماكيافيلي",
                            CategoryId = 8,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "من أكثر الكتب مبيعًا\n\nطبعة جيب أنيقة وجذابة\n\nاتهم الناس ماكيافيلي بأنه سنَّ في كتابه أقسى أساليب الاستغلال وأفظعها، وابتدع أظلم خطة للتحكم في الأعناق. لكن الحقيقة أن ماكيافيلي قضى عمره في خدمة أهل وطنه، والسعي في تأسيس بناء العدل ليعيشوا في ظله، وقد جلب عليه تطرفه للعدل والحق فقدان منصبه في جمهورية فلورنسا.\n\nكتب ماكيافيلي ما كتب ليدل الناس على مواطن الغدر، وليفطنوا إلى صنوف الخداع فيما يُدبَّر ضدهم، وما يُدَس لهم من الدسائس، ولو أن الناس تدبروا كتابه لما تمكن أحد من إيذائهم.\n\nلقد آنَ للقارئ أن ي",
                            ImageUrl = "/images/products/9789776743717.webp",
                            Isbn = "9789776743717",
                            Name = "الأمير",
                            Pages = 240,
                            Price = 110m,
                            PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Size = "12×17",
                            Stock = 10,
                            TopRated = false
                        },
                        new
                        {
                            Id = 141,
                            Author = "أحمد خالد توفيق",
                            CategoryId = 8,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "أغنية خيال علمي...\nهذا هو تقريبًا أدق وصف لهذه الأغنية القديمة التي قدمها الثنائي الأمريكي \"زاجر وإيفانز\" عام 1969. لقد حققت نجاحًا هائلًا آنذاك، حتى أنه كان بإمكانك سماعها طوال اليوم على محطات الراديو في مصر. ولوقت طويل، كانت هذه المقطوعة الموسيقية هي الخلفية الصوتية لأي عمل درامي يتعلق بالمستقبلية.\nتتخيل الأغنية حالة الإنسانية في عام 2525، ثم تقفز بزيادات قدرها 1010 سنة مع كل مقطع جديد. تُظهر لنا كيف ستتقدم البشرية، لكن في اتجاه معاكس لليوتوبيا، حيث يتحول البشر إلى كائنات شبيهة بالآلات المبرمجة. تناقش الأغنية ما يناقشه كل كاتب معاصر في مجال الخيال العلمي، مع نفس اللمسة من التشاؤم والقلق على مصير هذا الكوكب الجميل الذي هدّرنا موارده دون حساب.\nاللحن سريع ومبهج، لكنه ينقل أيضًا إحساسًا بالرهبة والغربة؛ تشعر وكأنك في سباق محموم مع آلة زمن مجنونة نحو نهاية مجهولة ومظلمة، دون رجعة؛ فأنت تندفع بلا توقف نحو الثقب الأسود.\n(الكتاب عبارة عن مجموعة من المقالات يكتب فيها الدكتور أحمد خالد توفيق عن الأغاني التي يحبها ويترجمها.)",
                            ImageUrl = "/images/products/9789778202243.webp",
                            Isbn = "9789778202243",
                            Name = "نشوات قديمة",
                            Pages = 432,
                            Price = 290m,
                            PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
