                        new
                        {
                            Id = 163,
                            Author = "نبيل فاروق",
                            CategoryId = 2,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "في زمنٍ ينهار فيه كل شيء، وتقترب البشرية من حافّة الفناء، تبدأ الحكايات الأخيرة في التكوّن.\nحكايات عن مدنٍ سقطت، وأحلامٍ تحوّلت إلى كوابيس، وأسرارٍ تُروى قبل أن يختفي آخر من يتذكرها.\nفي \"يوميات آخر البشر\"، يصحبنا د. نبيل فاروق في رحلة بين عوالم من الخيال العلمي والرعب والغموض، حيث لا يكون الإنسان دائمًا البطل… وأحيانًا لا يكون حتى الناجي الأخير.\nفهل ستكشف هذه اليوميات عن الأمل… أم عن النهاية التي لا مفرّ منها؟",
                            ImageUrl = "/images/products/9789778202816.webp",
                            Isbn = "9789778202816",
                            Name = "يوميات اّخر البشر",
                            Pages = 124,
                            Price = 170m,
                            PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
