                        },
                        new
                        {
                            Id = 164,
                            Author = "خولة حمدي",
                            CategoryId = 4,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "تدور أحداث القصة حول ريما، الفتاة المسلمة من تونس التي فقدت والديها. كانت آخر كلمات والدتها إلى جارتها اليهودية يعقوب أن يربيها على نهج الإسلام. كبرت الفتاة، وأخذت ترتدي الحجاب، فبدأت تعتبر يعقوب غريبًا عنها. حينها، طالبت زوجته تانيا أن يختار بينها وبين ريما التي أحبها كابنته. فقام بإرسالها إلى أخته راشيل في لبنان، لتتعقد الأمور عندما اضطرت إلى التنقل بسبب سوء معاملة زوج راشيل لها. وعاشت بعدها مع صديقة راشيل، سونيا، التي كانت من سكان تونس أيضًا لكنها فرت من زوجها التعسفي برفقة ابنتيها ندى ودانا إلى مدينة قانا في لبنان. وهكذا، تتشابك مصائر الجميع في دوامة من التعقيد.\nقصة عن الإنسانية، والأديان، والحب.",
                            ImageUrl = "/images/products/9789776376441.webp",
                            Isbn = "9789776376441",
                            Name = "في قلبي أنثى عبرية",
                            Pages = 388,
                            Price = 325m,
                            PublishDate = new DateTime(2013, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Size = "14×20",
                            Stock = 10,
                            TopRated = false
                        },
                        new
                        {
                            Id = 165,
                            Author = "خولة حمدي",
                            CategoryId = 4,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "في هذا الجزء الأخير، يبرز عمر وياسمين كشخصيات مركزية، حيث ينقل الكاتب مشاعرهما بعبقرية تجعل القارئ يشعر وكأنه يعيش كل لحظة من خلال قلبيهما.\nتتعمق الرواية في تناول قضايا اجتماعية وإنسانية متعددة، مؤكدةً على أهمية الأفراد المبادرين في المجتمع؛ فحتى أرقى الأعمال يمكنها أن تترك أثرًا دائمًا، مما يبرز القوة الهادئة للجهود الخيرية.\nكما تطرق القصة إلى أزمة اللاجئين السوريين والحرب الأهلية، لتأخذ القارئ في رحلة عبر الأردن، خاصةً مخيم الزعتري، إلى جانب تونس، والمغرب، وباريس، وجبال سويسرا الساحرة.\nبأسلوب جذاب ومشوق، تنسج هذه الثلاثية تسلسلاً قويًا من الأحداث، فتشد القارئ بسرد مميز يحافظ على انتباهه من البداية حتى النهاية.",
                            ImageUrl = "/images/products/9789778201338.webp",
