                        },
                        new
                        {
                            Id = 179,
                            Author = "طاهرة ماڤي",
                            CategoryId = 2,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "أنا محملة بلعنة، وأحمل هبةً في آنٍ واحد.\nأنا وحشٌ، ولكني أكثر من مجرد بشر.\nلمستي قاتلة، ولمستي تجسّد القوة.\nأنا سلاحهم، وسأنتقم.\n\nلم يمسّ جوليت أحدًا منذ 264 يومًا بالضبط.\nآخر مرة لمست فيها أحدًا كانت مجرد حادثة، لكن \"إعادة التأسيس\" سجنتها بتهمة القتل. لا أحد يعرف سبب فتك لمسة جوليت؛ وطالما أنها لا تؤذي أحدًا آخر، لا يُعيرها أحد اهتمامًا، فالعالم منشغل بانهيار ذاته إلى شظايا، والأمر لا يشغل بال أحد بفتاة تبلغ من العمر سبعة عشر عامًا.\nتفتك الأمراض بالسكان، ويصبح العثور على الطعام أمرًا نادرًا، والطيور لم تعد تحلّق، والغيوم باتت بلون خاطئ.\nأعلنت \"إعادة التأسيس\" أن طريقتها هي السبيل الوحيد لإصلاح الأمور، فأسَرعوا برمي جوليت في زنزانة. والآن، بعد أن زادت أعداد القتلى حتى بدأ الناجون يهمسون بالحرب، تغيرت وجهات نظرهم؛ فقد تكون جوليت أكثر من مجرد روح معذبة محشوة في جسد سام، وربما هي بالضبط ما يحتاجونه الآن.\nوعليه أن تختار: أن تكون سلاحًا، أو أن تكون محاربة.",
                            ImageUrl = "/images/products/9789778201109.webp",
                            Isbn = "9789778201109",
                            Name = "حطمني",
                            Pages = 336,
                            Price = 300m,
                            PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
