                        new
                        {
                            Id = 180,
                            Author = "طاهرة ماڤي",
                            CategoryId = 2,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "في الجزء الثاني  من سلسلة \"حطمني\" للمؤلفة الأكثر مبيعًا وفق نيويورك تايمز، طاهره مافي، كان من المفترض أن تكفي لمسة واحدة من جوليت لقتل وارنر، لكن مناعته الغامضة ضد قوتها القاتلة هزّتها وتركتها تتساءل لماذا فشل درعها الأخير أمام الشخص الذي تحتاج إلى حمايته بشدة.\nنجحت هي وآدم في الفرار من مكائد وارنر والانضمام إلى مجموعة من المتمردين، كثيرٌ منهم يمتلك قدرات خارقة. ستتمكن جوليت أخيرًا من محاربة \"إعادة التأسيس\" بنشاط ومحاولة إصلاح عالمها الممزق، وربما يساعدها هؤلاء الحلفاء الجدد في كشف سر مناعة آدم ووارنر ضد بشرتها القاتلة.\nعالم جوليت مليء بالإثارة عالية المخاطر والرومانسية المشوقة، ما يجعله مثاليًا لعشاق سلسلة \"الملكة الحمراء\" لفيكتوريا أفيارد وثلاثية \"أكثر العقول ظلاماً\" لألكسندرا براكن.\nوقد أشاد رانسوم ريجز، المؤلف رقم 1 بحسب نيويورك تايمز، في قوله: \"ملحمة مثيرة ومليئة بالمخاطر لاكتشاف الذات والحب الممنوع؛ سلسلة 'حطمني' قراءة لا بد منها لعشاق أدب الشباب الديستوبي—أو أي أدب!\"",
                            ImageUrl = "/images/products/9789778201536.webp",
                            Isbn = "9789778201536",
