                        new
                        {
                            Id = 190,
                            Author = "چيف ليندسي",
                            CategoryId = 3,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "تعرف على ديكستر مورغان، ذئب مهذب في ثوب الحملان؛ وسيم وساحر، لكن شيئًا من ماضيه جعله يعيش وفق قواعد مختلفة. إنه قاتل متسلسل يتبع قاعدة ذهبية واحدة تجعله محبوبًا للغاية: فهو يقتل الأشخاص السيئين فقط. كما أن عمله كخبير في تحليل بقع الدم في قسم شرطة ميامي يضعه في موقع مثالي لتحديد ضحاياه.\nلكن عندما تبدأ سلسلة من جرائم القتل الوحشية التي تحمل تشابهًا مذهلًا مع أسلوبه الخاص بالظهور، يجد ديكستر نفسه بين مديح مُبالغ فيه ورعب يغمره—هل هو خائف من نفسه أم من وحش آخر؟",
                            ImageUrl = "/images/products/9789778201086.webp",
