                        new
                        {
                            Id = 218,
                            Author = "عمرو المنوفي",
                            CategoryId = 9,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "\"كل ما تخشاه يكمن هناك... في أعماق الدارك ويب، وبداخل تلك الصناديق المشؤومة.\"\n\nعالم الانترنت، عالم مخيف، وأخطر طبقاته هي الانترنت المظلم، حيث كل شيء ممنوع، ومحرم، وخطر، متاح.\nولكن مالا تعرفونه، أن هناك طبقتين إضافيتين، لا يعلم عنهم إلا عدد لا يتجاوز أصابع اليد الواحدة في العالم كله، وتلك الطبقتان تحتويان على ما لا يخطر على بال كائن حي من أسرار وأهوال.\nمعا سنكتشف ما يوجد في (القبو).\nوفي الطابق الشبحي.\nوفي الصناديق المظلمة، التي يحتوي كل منها على لعنة رهيبة، أو سر مغلق، أو ....\nالكثير سنكتشفه معًا.",
                            ImageUrl = "/images/products/9789778202823.webp",
