                        new
                        {
                            Id = 313,
                            Author = "چورچ ر.ر مارتن",
                            CategoryId = 2,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "الرواية اللي أسرت قلوب ملايين حول العالم، بترجمة منقَّحة وغلاف جديد كليًّا!\n\n�في «صِدام الملوك»، يواصل چورچ ر. ر. مارتن نسج خيوط ملحمته العظيمة «أغنيَّة الجليد والنَّار».\nبعد موت الملك روبرت باراثيون واللورد إدارد ستارك، تغرق الممالك السَّبع في فوضى عارمة، ويرفع خمسة ملوك راياتهم في صراع لا يرحم على العرش الحديدي، لتبدأ موجة جديدة من الحروب، والتحالفات الغادرة، والعهود التي تُكسر كما تُسفك الدماء.\nفي أراضي النهر والغرب، يخوض روب ستارك معركة تلو معركة للانتقام لأبيه وتأمين مملكته الجديدة.\nوفي العاصمة، يجد تيريُن لانيستر نفسه وسط شبكة معقدة من المؤامرات فيما تستعد المدينة لهجوم ستانِس باراثيون، وتعيش سانزا في قلعة يزداد خطرها يومًا بعد يوم.\nووراء الجدار، يواجه چون سنو تحديات تهدِّد كل ما يعرفه عن الولاء والواجب.\nوفي الشرق في قارَّة أخرى، تواصل دنيرس تارجاريَن رحلتها بين مدن بعيدة، بحثًا عن القوة التى تمكِّنها من استعادة عرش أبيها الضائع.\nومع تصاعد النزاعات، يبدأ صدام هائل سيُعيد رسم خريطة القوة، ويُثبت أن في هذه اللعبة لا مكان للضعفاء، فإمَّا النصر وإمَّا السقوط.",
                            ImageUrl = "/images/products/9789778202946.webp",
                            Isbn = "9789778202946",
                            Name = "صدام الملوك (الجزء الثاني من اغنية الجليد والنار) سوفت كڤر (العالمي)",
                            Pages = 1314,
                            Price = 1020m,
                            PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Size = "14×20",
                            Stock = 10,
                            TopRated = false
                        },
                        new
                        {
                            Id = 314,
                            Author = "چورچ ر.ر مارتن",
                            CategoryId = 2,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "ما زالت حرب الملوك الخمسة مشتعلةً، تعاني ويلاتها جميع أنحاء الممالك السبع إلا قليلًا. على العرش الحديدي يجلس الملك الصبي الغاشم جوفري، فيما يسعى جدّه اللورد تايوين لانستر، يدُ الملك، لتأمين حكمه، ومن ثم تأمين السلطة لعائلة لانستر، مخططًا للقضاء على الملك ستانيس باراثيون الذي خرج مدحورًا من معركة الماء الأسود، وعلى الذئب الصغير روب ستارك الذي يقود حملةً في غرب البلاد رغم أنه فقد وطنه في الشمال.\n\nوفي تلك الأثناء تشقّ الملكة المنفية دينيرس تارجاريَن طريقها في قارّةٍ أخرى تُغرقها الدماء، بغية تحرير مئات الآلاف من العبيد والحصول على جيشٍ تستعيد به مملكتها، ومعها التنانين الثلاثة الحيّة الوحيدة في العالم.\n\nوفي الشمال يتحرّك جيشٌ جرّار من الهمج استعدادًا للهجوم على الجدار وغزو الممالك السبع، جيشٌ انضمّ إليه رجل حرس الليل جون سنو جاسوسًا، ولو أنّ شيئًا أسوأ منه يتقدّم من أقصى الشمال، العدوّ الحقيقي الذي ينشغل عنه الجميع تقريبًا بقتالهم، وقد لا تقدر جيوش الأرض كلّها على ردعه.",
                            ImageUrl = "/images/products/9789778203165.webp",
                            Isbn = "9789778203165",
                            Name = "عاصفة السيوف اغنية الجليد والنار : سوفت كڤر نسخة الشرق الأوسط",
                            Pages = 1534,
