                        new
                        {
                            Id = 326,
                            Author = "سانتياجو آلبارِث",
                            CategoryId = 3,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "خرج هابيل لانوثا من مركز الأمراض النفسية وهو يأمل أن يستعيد حياته السابقة مع زوجته وابنه وأصدقاءه، لكنه يجد خاله قد توفي وترك له ميراث عبارة عن بيت وأرض في قرية مويردِألماس.. وهي قرية معزولة عن العالم لها قواعدها الخاصة والتي فرضتها عائلة أوسِّت. يقرر هابيل لعيش هناك لفترة هو وعائلته في محاولة منه للتعافي وتذكر الماضي الذي كان بالنسبة له لغز كبير. لكن تحدث الكثير من المشكلات وتتكشف العديد من المفاجآت.",
