                        new
                        {
                            Id = 331,
                            Author = "روبرت چوردان",
                            CategoryId = 2,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "تدور عجلة الزمن وتأتي الأعمار وتذهب، تاركةً وراءها ذكريات تتحول إلى أسطورة. تتلاشى الأسطورة لتصبح خرافة، وحتى الخرافة تُنسى عندما يعود العصر الذي أنبتها. ما كان، وما سيكون، وما هو عليه الآن، قد يقع جميعه تحت ظل الظلام.\n\nتصل مويرين دامودرِد إلى \"حقول إيموند\" في مهمة للعثور على المنبأ عنه الذي سيقف ضد \"الظلام المطلق\"، ذلك الكيان الخبيث الذي يزرع بذور الفوضى والدمار. وعندما يغزو فريق شرير من نصف بشر ونصف وحوش القرية باحثين عن عدو سيدهم، تقنع مويرين راند آل ثور وأصدقائه بترك ديارهم والدخول إلى عالم أكبر لا يُتصوَّر، مليء بالمخاطر التي تكمن في الظلال والنور.",
                            ImageUrl = "/images/products/9789778201604.webp",
                            Isbn = "9789778201604",
                            Name = "عجلة الزمن - عين العالم (مجلدين)",
