                        },
                        new
                        {
                            Id = 349,
                            Author = "ماريسا ماير",
                            CategoryId = 2,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "حتى في المستقبل.. ثمة فتيات في محنة!\nبعدما خاطرت كريس بكل شيء لتحذير سندر من الخطة الشريرة للملكة لافانا، تواجه مشكلة طفيفة؛ حيث لبثت سجينة على متن قمر صناعي منذ طفولتها، لا تحظى برفقة عدا الشاشات الشبكية؛ كل هذا الوقت أمام الشاشة جعل من كريس قرصانة بارعة، ولسوء الحظ فقد تلقت لتوها أوامر من لافانا بتعقب سندر وشريكها الوسيم! وحين تخفق مجازفة إنقاذ كريس من قِبل سِندر وكابتن ثورن وسكارليت ووولف؛ تفترق المجموعة وتلوذ كريس أخيرًا بالفرار، إنما للحرية مقابل باهظ الثمن! في هذه الأثناء، لن تدع الملكة لافانا شيئًا يمنع زواجها من الإمبراطور كاي.\nربما لم تتطوع كريس وسكارليت وسندر لإنقاذ العالم، لكن عساهن أمله الوحيد!",
                            ImageUrl = "/images/products/9789778202502.webp",
                            Isbn = "9789778202502",
                            Name = "سلسلة سجلات القمر - كريس",
