                        },
                        new
                        {
                            Id = 350,
                            Author = "چيف ليندسي",
                            CategoryId = 3,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "هو وحش ساحر... بطل مُظلم... قاتل متسلسل يقتل السيئين فقط.\nيعاني ديكستر مورغان من ضغوط هائلة؛ فليس من السهل أن تكون قاتلًا متسلسلاً أخلاقيًا، خاصةً أثناء محاولته تجنب الشكوك التي لا تهتز من قبل الرقيب الخطير \"دوكس\" الذي يعتقد أن ديكستر مختل عقليًا... وهو بالطبع كذلك.\nفي محاولة لإبعاد دوكس عن أثره، اضطر ديكستر للغوص عميقًا في زيه المموه المحكم. وبينما لا يعمل كمحلل لبقع الدم في شرطة ميامي، يقضي معظم وقته مع صديقته المشرقة \"ريتا\" وطفليها، يحتسي بيرة خفيفة ويصبح ببطء أول \"مدمن قطنية\" في العالم.\nلكن إلى متى يستطيع ديكستر أن يلعب لعبة \"ركل العلبة\" بدلًا من \"تقطيع القاتل\"؟ إلى متى ستجبره \"الراكب المظلم\" بداخل نفسه على إسقاط التمثيل وإطلاق وحشه الداخلي؟\nفي أوقات الشدائد، تطرق الفرص الباب؛ إذ يظهر مهووس شرير بشكل خاص يشق طريقه عبر ميامي بأسلوب ملتوي يترك ديكستر عاجزًا عن الكلام. ومع اشتعال شهوته المظلمة من جديد، تنجذب أخته \"ديبورا\" (المحققة الجديدة الشرسة في ميامي) إلى القضية، فيتضح سريعًا أن الإمساك بوحش يتطلب وحشًا آخر—ولكن لن يتمكن ديكستر من الاستغراق في البحث عن هدف جديد حتى تُختطف عدوه اللدود، ما لم يُفاجئه هدفه أولاً…\nبذكاءٍ لا يُضاهى وبطابع جديد أضاف إليه \"جيف ليندسي\" تألقًا مبهرًا، يأخذ ديكستر مورغان إلى مستوى جديد من الجاذبية المُظلمة، مقدّمًا لنا أحد أكثر السرديين ابتكارًا وتلوّنًا منذ سنوات.",
                            ImageUrl = "/images/products/9789778201277.webp",
                            Isbn = "9789778201277",
                            Name = "دكستر - المتفاني بإخلاص",
                            Pages = 360,
                            Price = 290m,
                            PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
