                        },
                        new
                        {
                            Id = 351,
                            Author = "بوب براير",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "نظرة جديدة كبرى على كنوز وأسرار قبر توت عنخ آمون في الذكرى المئوية لاكتشافه.\nغالبًا ما يُعتقد أن قصة توت عنخ آمون انتهت حينما نُقلت آلاف القطع التي اكتشفها هوارد كارتر ولورد كارنايفون إلى المتحف المصري في القاهرة وعُرضت. لكن هناك المزيد في قصة توت عنخ آمون.\nفي \"توت عنخ آمون والقبر الذي غيّر العالم\" نتابع مائة عام من البحوث التي جرت منذ اكتشاف القبر: نتعلم أن العديد من القطع في القبر صُنعت من حديد نيزكي جاء من الفضاء الخارجي؛ وتظهر أدلة جديدة أن توت عنخ آمون ربما كان محاربًا دخل ساحة المعركة؛ ويأخذنا المؤلف \"بوب برايَر\" خلف كواليس عمليات الفحص بالأشعة المقطعية لمومياواته لكشف أسرار الفرعون.\nكما يسلط الكتاب الضوء على التأثير الواسع النطاق لاكتشاف قبر توت عنخ آمون على مجالات تتجاوز علم المصريات؛ حيث يتم فحص كيف أثر اكتشاف القبر على السياسة المصرية وساهم في سقوط الاستعمار في مصر. وعلى الصعيد العالمي، بدأت المعارض الضخمة التي ترفع مبالغ هائلة للمتحفّات في جميع أنحاء العالم مع توت عنخ آمون، كما نشأت فكرة توثيق كل قطعة تُكتشف في مكانها قبل نقلها. وإلى حد كبير، ساهمت \"توت مانيا\" التي أحاطت باكتشاف القبر في تعزيز الهوس الحديث بمصر القديمة.",
                            ImageUrl = "/images/products/9789778201482.webp",
                            Isbn = "9789778201482",
                            Name = "توت عنخ آمون و المقبرة التي غيرت العالم",
