                        },
                        new
                        {
                            Id = 352,
                            Author = "بيترفرونسكي",
                            CategoryId = 3,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "من خلال كُتب مثل (القتلة المُتسلسلين) و(القاتِلات المُتسلسِلات) و(أبناء قابيل)، رسَّخ بيتر فرونِسكي مكانته كخبيرٍ رائِد في تاريخ القتلة المُتسلسلين. في هذا السرد التاريخي، الأول والأخير، للعصر الذهبي للقتل المُتسلسِل في الولايات المُتحِدة الأمريكيَّة، حينما ارتفعَت أعداد القتلة المُتسلسلين وضحاياهُم بشكلٍ كبير، يروي فرونِسكي قصص أغرب وأبرز جرائِم القتل المُتسلسِل من الخمسينيَّات وحتى أوائِل القرن الحادي والعشرين. من تِد بندي إلى قاتِل الولاية الذهبيَّة، يزداد هوسنا بهؤلاء القتلة المُتسلسلين القدامى يومًا بعد توم. ويُقدِّم هذا الكِتاب لعُشَّاق الجرائِم الحقيقيَّة كُل ما يشتهونه، بدءً من الأسماء الشهيرة (مثل إد كِمبر وجيفري دامر)، وصولًا إلى القضايا الأقل شُهرة (مثل ميلفِن ريس وهارفي جلاتمان).",
                            ImageUrl = "/images/products/9789778202588.webp",
                            Isbn = "9789778202588",
                            Name = "القتله المتسلسلين الأمريكيين",
                            Pages = 614,
                            Price = 490m,
