                        new
                        {
                            Id = 393,
                            Author = "بيشوي القمص",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "مشروعات تشاوشيسكو المكلفة وحرية الاقتراض من الغرب أغرقت رومانيا في الديون إلى حد اضطرت معه الحكومة إلى تصدير بعض السلع على حساب الاستهلاك المحلي، وتدهور الاقتصاد الروماني إلى حد غير مسبوق، وانهارت مستويات المعيشة للغالبية العظمى من الرومانيين، حتى وصفت رومانيا في ذلك الوقت بإثيوبيا أوربا. ومع بداية الثمانينيات، أصبح سداد هذا الدين عبئًا كبيرًا على مالية الدولة، فقرر تشاوشيسكو سداد ديون رومانيا بالكامل، ونظم استفتاء على إجراء تعديل دستوري يمنع رومانيا من تلقي قروض من الخارج في المستقبل، وبناء على هذا القرار، جرى توجيه معظم الإنتاج الصناعي والزراعي للبلاد من أجل سداد الدين، وكانت نتيجة هذه الإجراءات كارثية على الأغلبية الساحقة من الشعب، حيث تم تعميم نظام الحصص من السلع الغذائية في جميع أنحاء البلاد باستثناء العاصمة، وجرى تقليص هذه الحصص على نحو مستمر، وتراجع استهلاك الطاقة بصورة مروعة، وتوقفت أنظمة التدفئة المركزية، وحتى التلفزيون الرسمي قلصت قنواته لتصبح قناة واحدة تبث لمدة ساعتين فقط يوميا، أما الكهرباء فكان يتم قطعها لساعات طويلة وخاصة في الليل من أجل التوفير، وبلغ الفقر وضيق المعيشة مستويات غير مسبوقة، وتم وقف الاستيراد بصورة شبه كاملة، باستثناء استيراد السلع الفاخرة لتشاوشيسكو والزمرة المحيطة به، حتي تم سداد ديون رومانيا كاملة في صيف 1989.",
                            ImageUrl = "/images/products/9789778200430.webp",
                            Isbn = "9789778200430",
                            Name = "لا احد يتعلم من التاريخ 2 - قيصر جديد",
