                        new
                        {
                            Id = 394,
                            Author = "بيشوي القمص",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "يقول الفيلسوف الألماني الشهير فريدرش هيجل \"نتعلم من التاريخ، أن أحداً لم يتعلم من التاريخ\"..\n على غرار الجزء الأول والثاني، يتناول الجزء الثالث من سلسلة \"لا أحد يتعلم من التاريخ\" صراع العروش في كل من سوريا والعراق، منذ اللحظة الأولى لأنطلاق الثورة العربية الكبرى من مكة على يد الشريف حسين بن علي الهاشمي، مروراً بتأسيس الممالك الأربعة في نجد والأردن وسوريا والعراق، ولعبة الكراسي الموسيقية بين عسكر سوريا حتى قيام الجمهورية العربية المتحدة وسقوطها، وصولاً لحكم الاسد وأبناءه، كما يتناول الكتاب تاريخ الملكية في العراق، والمطامع التاريخية في دولة الكويت، ولعبة الكراسي الموسيقية بين عسكر العراق وصولاً لحكم صدام حسين.",
                            ImageUrl = "/images/products/9789778201239.webp",
                            Isbn = "9789778201239",
                            Name = "لا أحد يتعلم من التاريخ 3 - صراع العروش بين سوريا والعراق",
