                        new
                        {
                            Id = 428,
                            Author = "مديحة ممدوح عارف",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "تدور احداث رواية مستعمرة ما بعد الموت عن مدينة تشتعل بها حرب خفية بين الطموح والخداع، ويغدو الدم أثمن من الذهب.تتحول الحياة إلى وباء، والماء إلى سرّ لا يُشرب، فيما ينهض من الرماد عالم لا يرحم.\nيهرب الناجون إلى حصنٍ بُني قبل النهاية بوقتٍ طويل، لكن جدرانه تعرف أكثر مما تُخفي.\nيعود الماضي ليحاكم الحاضر، وتتشابك الأزمنة كأنها تتنفس من جرحٍ واحد.\nوعندما يظهر \"الظل\"، يدرك الجميع أن الموت لم يكن سوى بداية المستعمرة.",
                            ImageUrl = "/images/products/9786339970375.webp",
