                        new
                        {
                            Id = 434,
                            Author = "نشوة أبوالوفا",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "بعد أن وقع العالم تحت وطأة الكورونا انقلبت كل الأمور رأسًا على عقب!\nظهر ابتلاء لا قِبل للبشر بمواجهته، في محاولات لإيجاد مخرج من ذلك الابتلاء تدور الصراعات.\nفهل سينتصر البشر؟!\nأم يندثرون تحت الثُرى مسطرين نهاية الكوكب الذي نعرفه؟!",
                            ImageUrl = "/images/products/9786339971044.webp",
                            Isbn = "9786339971044",
                            Name = "زوشادو",
                            Price = 150m,
                            PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
