                        new
                        {
                            Id = 436,
                            Author = "نشوة أبوالوفا",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "تدور أحداث الرواية عن الصراع ما بين القلب والعقل وحرب ما بين العادات ومواطن القوة والعزة في النفوس، عادات قديمة من الاعتزاز فقط بالذكر وتهميش واحتقار كامل للأنثى، فهل سيفرض القلب والرحمة سطوتهما أم يندثران تحت وطأة ظلم العادات الموروثة؟",
