                        new
                        {
                            Id = 583,
                            Author = "محمد مندور",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "هناك أسرار يجب أن تُدفن… وهناك أسرار يُقتل من يقترب منها.\n\nكل شيء بدأ بمعلومة صغيرة…\nملف قديم لا يجب أن يكون موجودًا.\n\nلكن عندما يفتح ياسين هذا الملف، يكتشف أن الحقيقة التي يبحث عنها لم تختفِ…\n\nبل تم محوها عمدًا.\n\nأسماء اختفت من السجلات. حوادث بلا شهود. وأشخاص يتذكرون أشياء… لم تحدث أبدًا.\n\nكل خيط يقوده إلى شبكة من الأسرار تعمل في الظل منذ سنوات. شبكة قادرة على فعل شيء أخطر من القتل…\n\nقادرة على محو الحقيقة نفسها.",
                            ImageUrl = "/images/products/9786338387617.webp",
                            Isbn = "9786338387617",
                            Name = "النسيان",
                            Price = 250m,
                            PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Stock = 10,
