                        new
                        {
                            Id = 586,
                            Author = "محمد مندور",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "بعض الملفات لا يجب أن تُفتح…\nوفي عالم الاستخبارات، هناك قاعدة غير مكتوبة:\nإذا اختفى الملف… فهناك من أراد للحقيقة أن تختفي معه.\nعندما يظهر فجأة ملف قديم يحمل الرمز C17، يكتشف بطل الرواية أن الأمر ليس مجرد وثيقة منسية في أرشيف سري.\nبل بداية طريق يقوده إلى شبكة من الأسرار التي دُفنت بعناية… وأشخاص مستعدون لفعل أي شيء حتى تبقى مدفونة.\nكل صفحة من الملف تكشف حقيقة أخطر من السابقة. أسماء لم يكن يجب أن تُذكر. عمليات لم تُسجل رسميًا.\nوأحداث… لم يُسمح للعالم أن يعرف بوقوعها.\nلكن المشكلة الحقيقية ليست في محتوى الملف.\nالمشكلة أن كل من اقترب من الحقيقة قبله… اختفى.\nوالآن أصبح هو التالي في القائمة.\nبين المطاردة، والخداع، والذكريات التي لا يمكن الوثوق بها، يجد نفسه أمام سؤال واحد:\nهل الحقيقة تستحق أن تموت من أجلها؟\n«ملف العميل 17»\nرواية تشويقية استخباراتية مشحونة بالغموض، تكشف عالم الظلال حيث لا شيء كما يبدو… وحيث قد يكون أخطر سلاح في العالم هو المعلومة.",
                            ImageUrl = "/images/products/9786338387655.webp",
                            Isbn = "9786338387655",
                            Name = "ملف العميل 17",
                            Price = 200m,
                            PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Stock = 10,
