                        new
                        {
                            Id = 617,
                            Author = "محمود النجار",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "ليس هذا الكتاب سيرة ذاتية بالمعنى التقليدي، ولا بحثًا أكاديميًا باردًا، ولا شهادة إنسانية عابرة تُكتب بدافع الألم فقط. إنه محاولة واعية لالتقاط لحظة تاريخية نادرة: لحظة يولد فيها الوعي من قلب الفقد، وتُعاد فيها صياغة المعرفة تحت الركام.\nكُتب هذا الكتاب في زمن لم تعد فيه الأسئلة النظرية منفصلة عن الدم، ولم يعد فيه الكاتب قادرًا على الاحتماء خلف حياد زائف أو لغة محايدة. في زمن الإبادة، يصبح الصمت موقفًا، ويغدو البحث إما فعل مسؤولية أو شريكًا في التواطؤ. من هنا، لا يقدم هذا الكتاب إجابات جاهزة، بل يطرح أسئلة أخلاقية ومعرفية عميقة حول دور الإنسان، والكاتب، والتقنية، والمعرفة في عالم تتآكل فيه القيم أمام آلة العنف.",
                            ImageUrl = "/images/products/9786338419172.webp",
                            Isbn = "9786338419172",
                            Name = "من تحت الركام ولد الوعي",
                            Price = 150m,
