                        new
                        {
                            Id = 689,
                            Author = "مصطفي عبيد",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "\"مصر في منتصف القرن العشرين، ساحة عراك دامٍ، تتبدل فيه الأدوار، وتتغير المواقع حتى لا يبين غالب من مغلوب. منكسرون بالتبعية يرون جلاء المحتل رهانًا مستبعدًا يحسُن تأجيله على الدوام، وجامحون طامحون يحصون خطاهم للتجهز لحكم البلاد والعباد شرقًا وغربًا بعد تحرر يؤمنون أنه صار وشيكًا، وبين الفريقين منتفعون دومًا في النصر والهزيمة، لديهم قدرات معجزة على التلون وتبديل المواقف، وعصر القيم للمواءمة مع كل حال طلبًا للمكسب\".\n   لعب القدر لعبته  العجيبة، فألقى بين يدي المؤلف نصًا ممنوعًا ظل الاقتراب من أحداثه عملًا محرمًا لسنوات طويلة تتحدث فيه شخصية استثنائية، لعبت أدوارًا سرية في تاريخ مصر المعاصر، وكانت شاهدة على أحداث وأسرار سياسية وأدبية خطيرة.\n وقد لجأ المؤلف إلى فن السرد الروائي تجنبًا للمساءلة القانونية.\nاسم المؤلف :- مصطفى عبيد\nسنة النشر :- 2024",
                            ImageUrl = "/images/products/9789777954853.webp",
                            Isbn = "9789777954853",
                            Name = "ابنة الديكتاتور",
                            Price = 245m,
