                        new
                        {
                            Id = 691,
                            Author = "هدى النعيمي",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "أخرجت الكتاب الابيض الذي يحتوي على الوردة الجافة، بدأت اكتب مذكرات شهلا، منذ حطت أقدامي على هذه الأرض التي أحببتها، وحتى هوى صرح الخيال، مع خصلات شعري الأسود تسقط على أرض غرفتي، دون أن أشعر بالحزن أو الحسرة بدأت بالسلام على زعفرانة، أمي صاحبة الكتاب، والتي اوصتني به خيراً، دون أن تذكر دون أن تذكر انه كتاب مذكرات، أو كتاب للعودة حين تهوى الصروح الكبيرة، بدأت بالسلام على أمي وكأني أكتب رسالة، تذكرت أنني لم أكتب رسائل الى أمي منذ أكثر من ستة أشهر، ولا أعرف إن كانت رسائلى التي أبعث بها إلى العاصمة في بلدي، ثم تنتقل باليد، من هذا إلى ذاك لا أعرف كم رسالة وصلت إلى أمي، بدأت أكتب مذكرات شهلا، لتصير يوماً إلى يد أمي. \nاسم المؤلف :- هدى النعيمى \nسنة النشر :- 2024",
                            ImageUrl = "/images/products/9789777954778.webp",
