                        new
                        {
                            Id = 727,
                            Author = "نبيل بن عبدالله الحصين",
                            CategoryId = 8,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "يرصد المؤلف –من خلال هذا الكتاب- محاولة لفهم التطور الخُلقي للإنسان، وتقييم تاريخنا، قبل الإسلام وبعده، والإسهام في الإجابة على سؤال متكرر في واقعنا العربي منذ أكثر من قرنين: لماذا تأخرت أمة العرب وتقدمت أمم أخرى؟ كما يرصد ويحلل تداعيات بعض الأحداث والمحطات المفصلية التي ساهمت في التأثير على بعض شرائح المجتمع السعودي ومنظومته القيمية والأخلاقية والسلوكية.\nويستعرض لمحة عن برامج ومُبادرات رؤية 2030 في ضوء مرتكزها القِيَمي والأخلاقي، ويغوص في واقع المجتمع السعودي، حتى لا يكون مخطوطة نظرية إنشائية بعيدة عن الواقع أو منفصلة عنه.\nويخلص إلى عرض مقترح لفكرة مشروع (برنامج وطني لتعزيز القيَم والأخلاق والسلوك الحضاري).\nفي النهاية، الكتاب ليس محاولة للتنظير أو فرض أي شيء، وليس جلدًا للذات، إنما وجهة نظر واجتهاد وأمنية تهدف لمزيد من الارتقاء \"الحضاري\" والريادة للوطن.\nــــــــــــــــــــــــــــــــ\nنبيل بن عبد الله الحصين: ولد عام 1959م بمكة المكرمة. حصل على بكالوريوس إدارة أعمال دولية وماجستير إدارة عامة من كاليفورنيا بالولايات المتحدة الأمريكية. عمل مديرًا للشؤون الإدارية والمالية بالملحقية التعليمية السعودية بكاليفورنيا، ثم رئيسًا لقسم الميزانية والتقارير بمحطات الساحل الغربي بالمؤسسة العامة لتحلية المياه بجدة، ثم مديرًا عامًا إقليميًّا للقطاع الغربي بشركة توكيلات الجزيرة للسيارات. وكان عضوًا لمجلس إدارة مؤسسة عكاظ للصحافة والنشر لدورتين متتاليتين ولايزال عضوًا مساهمًا بالمؤسسة.\nاسم المؤلف :- نبيل عبد الله الحصين\nسنة النشر :- 2024",
                            ImageUrl = "/images/products/9789777954334.webp",
                            Isbn = "9789777954334",
