                        },
                        new
                        {
                            Id = 730,
                            Author = "نهلة كرم",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "لم تخبر نورا أحدًا بما حدث لها في طفولتها ومراهقتها، اعتادت أن تخفي كل شيء داخلها ولا تبوح بما تشعر به، لكنها في لحظة لم تستطع الكتمان، فابتكرت لعبتها الخاصة، وصارت تستدعيه كل يوم إلى فراشها قبل النوم، تحكي أشياء وتخفي أخرى، ليلة بعد ليلة انكشف كل شيء داخلها، غيرتها، خوفها مما حدث، شعورها بالذنب وبالغضب، ولم يعد أمامها سوى مواجهة ظلامها.\nفي هذه الرواية تغوص نهلة كرم داخل الذات الإنسانية بكل تناقضاتها، الحب والكراهية، الصدق والكذب، البراءة والإثم، لنكتشف مع كل صفحة أن ما يظهر خارج النفس البشرية لا يعادل شيئًا مما داخلها.\nـــــــــــــــــــــــــــــــــــــ\nنهلة كرم: كاتبة مصرية من مواليد عام 1989، تخرجت في كلية الإعلام جامعة القاهرة، صدر لها مجموعتان قصصيتان: \"أن تكون معلقًا في الهواء\" و\"الموت يريد أن أقبل اعتذاره\"، وروايتان: \"المقاعد الخلفية\"، التي حصلت على جائزة ساويرس عام 2019، و\"خدعة الفلامنجو\"، التي وصلت للقائمة الطويلة لكتارا عام 2023.\nاسم المؤلف :- نهلة كرم \nسنة النشر :- 2023",
                            ImageUrl = "/images/products/9789777954310.webp",
                            Isbn = "9789777954310",
                            Name = "على فراش فرويد",
                            Price = 235m,
