                        new
                        {
                            Id = 760,
                            Author = "كاميليا حسين",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "تبرع كاميليا حسين في محو واستبعاد كل ما يفيض عن الحاجة، ويمكن استنتاجه من بين السطور، ومعيار البراعة هنا أن هذا المحو لا يجلب تعتيمًا بقدر ما يُكثِّف حضور المكتوب ويُضيئه، على طريقة الرسام الفرنسي جورج دي لاتور في توظيف التضاد بين الضوء والعتمة للوصول إلى أقصى درجات التعبيرية في لوحاته.\nمنصورة عز الدين\nلا تحمل «استغماية» شيئًا من عثرات الأعمال الأولى لكُتَّابها، حيث يتجلى إحكام البنية، وتتجلى مهارة الحذف والقدرة على قول الكثير من خلال القليل من الكلمات.\nعزت القمحاوي\n«استغماية» نص مدهش، مكتوب بسلاسة سردية لافتة، من خلال لغة بها الكثير من العذوبة، وصدق عظيم في نقل المشاعر ينم عن موهبة حقيقية.\nأشرف العشماوي\nهذه هي الرواية القصيرة الفائزة بجائزة «ورشة أصوات وخطوط لرواية الجريمة الأدبية» التي نظمتها «ستوريتل» للكتب الصوتية بالتعاون مع  الدار المصرية اللبنانية خلال الفترة من 15 مارس حتى 15 سبتمبر 2022، وقد أفرزت الورشة سبع روايات قصيرة تضخ دماءً جديدة ومبشرة في شرايين الإبداع المصري والعربي.\nالناشر\nالرواية نتاج ورشة كتابة «ستوريتل» للكتب الصوتية بالتعاون مع  الدار المصرية اللبنانية\nاسم المؤلف :- كاميليا حسين \nسنة النشر :- 2023",
                            ImageUrl = "/images/products/9789777954075.webp",
                            Isbn = "9789777954075",
                            Name = "استغماية",
