                        new
                        {
                            Id = 765,
                            Author = "محمد فريد بك",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "هذا الكتاب يُعد من بواكير الكتابات التاريخية الجديدة، فقد كُتب في نهاية القرن التاسع عشر ليؤرِّخ للدولة العثمانية ويُقدِّمها لقارئ اللغة العربية، وهو بشكلٍ عام يميل إلى السرد التاريخي بعيدًا عن النقد والتحليل، إلا فيما ندر.\nورغم أن هدف مؤلِّفه محمد فريد بك كان الاستقواء بالدولة العثمانية في مواجهة الاحتلال الإنجليزي لمصر، لكنه يبقى كتابًا تاريخيًّا ممتازًا؛ إذ إن المؤلف دقَّق في معلوماته، وضمَّنه نصوص المعاهدات والاتفاقيات التي ترجمها من اللغة التركية.\nوقد رصد محمد فريد طبيعة تحول السُّلطة وممارستها في الدولة العثمانية، بدايةً من تحديد سُلطة الصدر الأعظم وضرب العُملة من الذهب والفضة، وتحويل الجيوش إلى نظامية منضبطة، بعد أن كانت تُستدعى وقت الحرب من القبائل.\nكما أشار المؤلف إلى بداية تلقيب سلاطين آل عثمان بخلفاء المسلمين، حيث بدأها السلطان عبد العزيز في القرن التاسع عشر، كمحاولةٍ للتغلب على ضعف الدولة العثمانية واهتزاز صورتها، بهدف تكتيل الرأي العام واستغلال انتشار المسلمين حول العالم.\nويرصد الكتاب كذلك قيام الدولة العثمانية بمنح الدول الأورُبية امتيازات لم تكُن سوى هِبات سُلطانية ومِنح لها عوائد ماليَّة ضخمة على حساب الدولة وشعبها دون مقابل يُذكر سوى الصداقة والمحبة!\nاسم المؤلف :- محمد فريد بك \nسنة النشر :- 2023\n\nتقديم وتعليق خالد عزب",
                            ImageUrl = "/images/products/9789777953993.webp",
